INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(319324, 24260, 1143, '<td valign="top">I love this. I just wish it made me think "office" more... it may be your office, but I doubt many other ppl would get that idea from it. Still... VERY cool.</td>', 'I love this. I just wish it made me think "office" more... it may be your office, but I doubt many other ppl would get that idea from it. Still... VERY cool.', '2003-06-09 01:22:17.000000', NULL, 1),
(319327, 24276, 2279, '<td valign="top">I love the sketch and the setup but what really bothers me is the intensity of the blues. Almost as if you bumped up the contrast a little too much.</td>', 'I love the sketch and the setup but what really bothers me is the intensity of the blues. Almost as if you bumped up the contrast a little too much.', '2003-06-09 01:26:11.000000', NULL, 1),
(319329, 24176, 2279, '<td valign="top">Great photo... now if only we could spot edit you could remove the white spots above the point of the letter opener.</td>', 'Great photo... now if only we could spot edit you could remove the white spots above the point of the letter opener.', '2003-06-09 01:28:31.000000', NULL, 1),
(319332, 24202, 772, '<td valign="top">I think this is my favorite shot out of the challenge... I have a set of these that I keep on my desk.  I have some painted ones like this but i have a stainless steel set also... great relaxation :) = 10 - setzler</td>', 'I think this is my favorite shot out of the challenge... I have a set of these that I keep on my desk.  I have some painted ones like this but i have a stainless steel set also... great relaxation :) = 10 - setzler', '2003-06-09 01:29:16.000000', NULL, 1),
(319337, 23962, 7038, '<td valign="top">Is this a stapler? It looks like a 2 hole punch.  Very good pic though, I like the lighting and the antiqueness of the item</td>', 'Is this a stapler? It looks like a 2 hole punch.  Very good pic though, I like the lighting and the antiqueness of the item', '2003-06-09 01:36:43.000000', NULL, 1),
(319339, 24253, 1143, '<td valign="top">this is very nice. love the deep blue. i''d get rid of the advertisement.</td>', 'this is very nice. love the deep blue. i''d get rid of the advertisement.', '2003-06-09 01:39:00.000000', NULL, 1),
(319341, 24006, 1280, '<td valign="top">Using the cup to complete the "R" is brilliant!!!  Very creative...keep up the good work.  :-)<br/>Grayce</td>', 'Using the cup to complete the "R" is brilliant!!!  Very creative...keep up the good work.  :-)Grayce', '2003-06-09 01:42:12.000000', NULL, 1),
(319343, 24275, 7038, '<td valign="top">Looks a little too pixelated</td>', 'Looks a little too pixelated', '2003-06-09 01:47:01.000000', NULL, 1),
(319351, 24276, 1143, '<td valign="top">simplify. the drawing is really cool. get rid of somet of the other stuff</td>', 'simplify. the drawing is really cool. get rid of somet of the other stuff', '2003-06-09 01:57:23.000000', NULL, 1),
(319354, 24099, 1280, '<td valign="top">Lol...good one!  Made  me chuckle.</td>', 'Lol...good one!  Made  me chuckle.', '2003-06-09 02:02:43.000000', NULL, 1),
(319358, 24102, 1280, '<td valign="top">Excellent!!!  Rich, vibrant, and beautifully composed. Nice abstract.</td>', 'Excellent!!!  Rich, vibrant, and beautifully composed. Nice abstract.', '2003-06-09 02:14:03.000000', NULL, 1),
(319361, 24046, 2279, '<td valign="top">Wow...I love technology. Great shot. Really nice complete black background.</td>', 'Wow...I love technology. Great shot. Really nice complete black background.', '2003-06-09 02:15:17.000000', NULL, 1),
(319371, 24260, 2279, '<td valign="top">I would have used as much DOF as possible for this shot to make as many of the caps as possible in focus. Buts thats just me and it may have been out of your control.</td>', 'I would have used as much DOF as possible for this shot to make as many of the caps as possible in focus. Buts thats just me and it may have been out of your control.', '2003-06-09 02:31:19.000000', NULL, 1),
(319372, 23962, 2279, '<td valign="top">Looks more like a hole punch to me. But nice placement none the less.</td>', 'Looks more like a hole punch to me. But nice placement none the less.', '2003-06-09 02:32:06.000000', NULL, 1),
(319388, 24230, 255, '<td valign="top">wow! this is fabulous! perfect tones and composition--what a wonderfully bizarre take on the challenge--i love it! 10</td>', 'wow! this is fabulous! perfect tones and composition--what a wonderfully bizarre take on the challenge--i love it! 10', '2003-06-09 03:24:29.000000', NULL, 1),
(319391, 23992, 255, '<td valign="top">for some reason this humor reminds me of mag! absolutely fabulous shot--love everything about it--the lighting, contrast, composition--basically the whole mise-en-scene! id put this on my office wall for sure. 10</td>', 'for some reason this humor reminds me of mag! absolutely fabulous shot--love everything about it--the lighting, contrast, composition--basically the whole mise-en-scene! id put this on my office wall for sure. 10', '2003-06-09 03:28:38.000000', NULL, 1),
(319394, 24001, 2279, '<td valign="top">Negative color photos just dont do it for me.</td>', 'Negative color photos just dont do it for me.', '2003-06-09 03:35:22.000000', NULL, 1),
(319401, 24043, 8533, '<td valign="top">DOF is too shallow for my liking.</td>', 'DOF is too shallow for my liking.', '2003-06-09 03:55:04.000000', NULL, 1),
(319406, 24219, 8533, '<td valign="top">This doesn''t make me think of offices in the slightest.</td>', 'This doesn''t make me think of offices in the slightest.', '2003-06-09 03:57:07.000000', NULL, 1),
(319410, 24108, 8533, '<td valign="top">A little too busy.The blue one doesn''t seem to stand out as much as I would expect it to.</td>', 'A little too busy.The blue one doesn''t seem to stand out as much as I would expect it to.', '2003-06-09 03:59:20.000000', NULL, 1),
(319427, 24219, 8643, '<td valign="top">Tilted to the left and you lost one car.  Didn''t say office to me.</td>', 'Tilted to the left and you lost one car.  Didn''t say office to me.', '2003-06-09 05:01:31.000000', NULL, 1),
(319428, 24138, 8643, '<td valign="top">Clever idea, clean picture, maybe too much red saturation - lost the detail in the red nib.</td>', 'Clever idea, clean picture, maybe too much red saturation - lost the detail in the red nib.', '2003-06-09 05:02:43.000000', NULL, 1),
(319430, 24125, 8643, '<td valign="top">Great idea, sepia is just right, like it vry much.</td>', 'Great idea, sepia is just right, like it vry much.', '2003-06-09 05:06:50.000000', NULL, 1),
(319433, 24204, 8643, '<td valign="top">Would have better in focus, without the rail across the bottom.</td>', 'Would have better in focus, without the rail across the bottom.', '2003-06-09 05:10:11.000000', NULL, 1),
(319434, 23962, 8643, '<td valign="top">Nicely photographed.</td>', 'Nicely photographed.', '2003-06-09 05:11:10.000000', NULL, 1),
(319436, 23729, 8643, '<td valign="top">Neat idea but it needed some context background.</td>', 'Neat idea but it needed some context background.', '2003-06-09 05:13:19.000000', NULL, 1),
