(319447, 23782, 8643, '<td valign="top">I think it may have been better without the second out of focus figure, or have I missed something?</td>', 'I think it may have been better without the second out of focus figure, or have I missed something?', '2003-06-09 05:28:07.000000', NULL, 1),
(319448, 24230, 8643, '<td valign="top">Clipped highlights spoiled a really nice idea.</td>', 'Clipped highlights spoiled a really nice idea.', '2003-06-09 05:28:55.000000', NULL, 1),
(319449, 24266, 8643, '<td valign="top">I smiled, nice thought!  Great composition, like the sepia too!</td>', 'I smiled, nice thought!  Great composition, like the sepia too!', '2003-06-09 05:35:50.000000', NULL, 1),
(319453, 24098, 772, '<td valign="top">Good macro... a little grainy...</td>', 'Good macro... a little grainy...', '2003-06-09 06:13:32.000000', NULL, 1),
(319454, 23656, 7857, '<td valign="top">Nice picture, I like the symmetry of the teeth you''ve placed there. I personally might have tried with softer lighting so the shadow off the drill wasn''t so harsh. Good job.</td>', 'Nice picture, I like the symmetry of the teeth you''ve placed there. I personally might have tried with softer lighting so the shadow off the drill wasn''t so harsh. Good job.', '2003-06-09 06:19:22.000000', NULL, 1),
(319455, 24142, 7857, '<td valign="top">Nice, I can see this hanging in an office for sure. The black and white looks nice, good lighting. But what is it? I''m thinking you''ve cut thin strips of paper, no? Anyway, great job.</td>', 'Nice, I can see this hanging in an office for sure. The black and white looks nice, good lighting. But what is it? I''m thinking you''ve cut thin strips of paper, no? Anyway, great job.', '2003-06-09 06:21:03.000000', NULL, 1),
(319456, 24047, 7857, '<td valign="top">Nice picture, but seems a bit cluttered. The gold of the compass and pencil look great with the colour of the map, nice lighting - 7</td>', 'Nice picture, but seems a bit cluttered. The gold of the compass and pencil look great with the colour of the map, nice lighting - 7', '2003-06-09 06:26:40.000000', NULL, 1),
(319459, 24262, 7857, '<td valign="top">Nice picture, nice concept, though I''m not sure I really like the background you''ve used in picture. Shame you weren''t able to get rid of the globe, I find it intrudes now and then as well.</td>', 'Nice picture, nice concept, though I''m not sure I really like the background you''ve used in picture. Shame you weren''t able to get rid of the globe, I find it intrudes now and then as well.', '2003-06-09 06:30:18.000000', NULL, 1),
(319460, 24204, 7857, '<td valign="top">Nice cubject, shame you couldnt do anything about the lighting its a bit bright for my liking coming from the right. A sharper focus would have been nice.</td>', 'Nice cubject, shame you couldnt do anything about the lighting its a bit bright for my liking coming from the right. A sharper focus would have been nice.', '2003-06-09 06:33:06.000000', NULL, 1),
