(319466, 23799, 8533, '<td valign="top">Certainly fits the challenge but not especially interesting to view.</td>', 'Certainly fits the challenge but not especially interesting to view.', '2003-06-09 06:46:11.000000', NULL, 1),
(319467, 24247, 8533, '<td valign="top">I can''t see anything in particular that strikes me as being wrong about this but it doesn''t engage me.</td>', 'I can''t see anything in particular that strikes me as being wrong about this but it doesn''t engage me.', '2003-06-09 06:46:56.000000', NULL, 1),
