(319676, 23908, 7758, '<td valign="top">I think the title is clever, not sure the globs of blue-tack are that appealing..... I think you are on the right track though.... good luck, Todd.</td>', 'I think the title is clever, not sure the globs of blue-tack are that appealing..... I think you are on the right track though.... good luck, Todd.', '2003-06-09 13:21:54.000000', NULL, 1),
(319677, 24154, 5391, '<td valign="top">Excellent use of light to bring out the gorgeous warm tones you''ve captured in this image.  This is remarkably well done.  Really gives the viewer a sense of feeling, as if you were standing in the photograph.  10</td>', 'Excellent use of light to bring out the gorgeous warm tones you''ve captured in this image.  This is remarkably well done.  Really gives the viewer a sense of feeling, as if you were standing in the photograph.  10', '2003-06-09 13:22:16.000000', NULL, 1),
