(319693, 23782, 5391, '<td valign="top">Great lighting - no ugly shadows or bright spots.  Makes this shot look very professional.  Nice use of DOF, also.  9</td>', 'Great lighting - no ugly shadows or bright spots.  Makes this shot look very professional.  Nice use of DOF, also.  9', '2003-06-09 13:35:14.000000', NULL, 1),
