(319726, 24274, 7857, '<td valign="top">Nice shot, nice DOF, black and white was a nice choice. Good luck with it.</td>', 'Nice shot, nice DOF, black and white was a nice choice. Good luck with it.', '2003-06-09 13:59:08.000000', NULL, 1),
