(319736, 23962, 7857, '<td valign="top">Stapler? Or is that office equipment sarcasm ;o) Nice subject, nice lighting (I can imaging that a harsh shadow would look bad, but then no shadow would look boring, so good job!)</td>', 'Stapler? Or is that office equipment sarcasm ;o) Nice subject, nice lighting (I can imaging that a harsh shadow would look bad, but then no shadow would look boring, so good job!)', '2003-06-09 14:04:50.000000', NULL, 1),
(319738, 24100, 7857, '<td valign="top">How did you do this? A nice idea, a sharper focus would have been nice but I can understand how that would be difficult if you are dealing with flying paper clips. Good luck with it.</td>', 'How did you do this? A nice idea, a sharper focus would have been nice but I can understand how that would be difficult if you are dealing with flying paper clips. Good luck with it.', '2003-06-09 14:06:21.000000', NULL, 1),
(319739, 24125, 3669, '<td valign="top">Very nice!  I like the set-up here.  The duotone is effective and looks vintage.  I like the single light source from the lamp.  Very much meets challenge and hope you get a good result.  10</td>', 'Very nice!  I like the set-up here.  The duotone is effective and looks vintage.  I like the single light source from the lamp.  Very much meets challenge and hope you get a good result.  10', '2003-06-09 14:06:45.000000', NULL, 1),
