INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(320021, 24088, 9262, '<td valign="top">background has too much light for my tastes. Shot is a little grainy. Nice composition</td>', 'background has too much light for my tastes. Shot is a little grainy. Nice composition', '2003-06-09 19:47:52.000000', NULL, 1),
(320023, 24267, 9262, '<td valign="top">Very nice shot. The bottom left is a little overexposed. Great composition</td>', 'Very nice shot. The bottom left is a little overexposed. Great composition', '2003-06-09 19:48:38.000000', NULL, 1),
(320024, 23645, 9262, '<td valign="top">Nice idea, too much light!</td>', 'Nice idea, too much light!', '2003-06-09 19:49:03.000000', NULL, 1),
