(320026, 24026, 9262, '<td valign="top">Humourous! Like the title and composition. Perspective and angles are good too.</td>', 'Humourous! Like the title and composition. Perspective and angles are good too.', '2003-06-09 19:50:51.000000', NULL, 1),
(320027, 24246, 9262, '<td valign="top">Nice shot. I especially like the lower right with the shaving coming ou of the frame! Great idea</td>', 'Nice shot. I especially like the lower right with the shaving coming ou of the frame! Great idea', '2003-06-09 19:51:38.000000', NULL, 1),
(320028, 24263, 9262, '<td valign="top">Nice shot on an everyday item. Good perspective and framing.</td>', 'Nice shot on an everyday item. Good perspective and framing.', '2003-06-09 19:53:00.000000', NULL, 1),
(320029, 24220, 9262, '<td valign="top">Nice shot! Good reflection.</td>', 'Nice shot! Good reflection.', '2003-06-09 19:54:23.000000', NULL, 1),
(320031, 23992, 9262, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2003-06-09 19:55:32.000000', NULL, 1),
(320032, 24102, 4564, '<td valign="top">Absolutely great! Fantastic colors. Excellent use of water drops. great composition. Nice crop and frame.  10.</td>', 'Absolutely great! Fantastic colors. Excellent use of water drops. great composition. Nice crop and frame.  10.', '2003-06-09 19:55:50.000000', NULL, 1),
(320033, 24138, 4564, '<td valign="top">Wonderful. Excellent use of colors.  Nice composition. 10.</td>', 'Wonderful. Excellent use of colors.  Nice composition. 10.', '2003-06-09 19:56:17.000000', NULL, 1),
(320034, 24187, 4564, '<td valign="top">Very dramatic.  Superb.  The blue glow is the cherry on the sunday for this photo.  Lovely. 10</td>', 'Very dramatic.  Superb.  The blue glow is the cherry on the sunday for this photo.  Lovely. 10', '2003-06-09 19:56:44.000000', NULL, 1),
