(320038, 24006, 9262, '<td valign="top">the background is distracting and the lighting is overexposed. Good idea</td>', 'the background is distracting and the lighting is overexposed. Good idea', '2003-06-09 19:59:30.000000', NULL, 1),
(320039, 24230, 4564, '<td valign="top">Very nice shot. Excellent composition. Original use of paperclips.  Lovely hair detail.  Too bad the skin seems to have so much grain in it... I wonder where it comes from?  8</td>', 'Very nice shot. Excellent composition. Original use of paperclips.  Lovely hair detail.  Too bad the skin seems to have so much grain in it... I wonder where it comes from?  8', '2003-06-09 19:59:57.000000', NULL, 1),
