(321201, 24142, 3306, '<td valign="top">Nice setup. I really like the lines. Well done. 8</td>', 'Nice setup. I really like the lines. Well done. 8', '2003-06-11 00:31:00.000000', NULL, 1),
(321203, 24259, 3306, '<td valign="top">Excellent setup, focus, lighting and color. I like your choice of backround.</td>', 'Excellent setup, focus, lighting and color. I like your choice of backround.', '2003-06-11 00:31:58.000000', NULL, 1),
(321205, 23843, 3306, '<td valign="top">What does this have to do with the office? Staying late at work?</td>', 'What does this have to do with the office? Staying late at work?', '2003-06-11 00:33:06.000000', NULL, 1),
(321224, 24266, 6900, '<td valign="top">Would''ve been interesting without the desat - the towel is too white.  Nice idea overall, but I''m not sure this is "take your camera to the office."</td>', 'Would''ve been interesting without the desat - the towel is too white.  Nice idea overall, but I''m not sure this is "take your camera to the office."', '2003-06-11 00:43:14.000000', NULL, 1),
(321225, 24257, 6900, '<td valign="top">Looks a little out of focus - good idea, excellent composition.</td>', 'Looks a little out of focus - good idea, excellent composition.', '2003-06-11 00:43:35.000000', NULL, 1),
(321227, 24264, 6900, '<td valign="top">Little too bright - some highlights got blown out and there is a loss of detail because of your contrast.</td>', 'Little too bright - some highlights got blown out and there is a loss of detail because of your contrast.', '2003-06-11 00:44:16.000000', NULL, 1),
(321228, 24004, 6900, '<td valign="top">Heh. Looks like my idea of a circular file.  Throw away everything you don''t want, see what''s left....oh wait, not much!  Good idea, good shot.</td>', 'Heh. Looks like my idea of a circular file.  Throw away everything you don''t want, see what''s left....oh wait, not much!  Good idea, good shot.', '2003-06-11 00:44:53.000000', NULL, 1),
(321230, 24002, 6900, '<td valign="top">Excellent sharpness on the center, not sure why you''d choose a low DoF for this, though.  Interesting subject.</td>', 'Excellent sharpness on the center, not sure why you''d choose a low DoF for this, though.  Interesting subject.', '2003-06-11 00:45:41.000000', NULL, 1),
(321231, 23729, 6900, '<td valign="top">Very dusty/dirty - wouldn''t have looked better cleaned up to look like we were there 1929 not that this came from 1929?</td>', 'Very dusty/dirty - wouldn''t have looked better cleaned up to look like we were there 1929 not that this came from 1929?', '2003-06-11 00:46:18.000000', NULL, 1),
(321233, 24216, 6900, '<td valign="top">HAHA - if they all had a note/writing on them, you''d get a 10.  Nice idea - this is SO what an office looks like.  Good DoF.  9</td>', 'HAHA - if they all had a note/writing on them, you''d get a 10.  Nice idea - this is SO what an office looks like.  Good DoF.  9', '2003-06-11 00:46:47.000000', NULL, 1),
(321234, 24232, 6900, '<td valign="top">Cool!  I like these - where''d you get em?  Did you make them?  Super cool.  8</td>', 'Cool!  I like these - where''d you get em?  Did you make them?  Super cool.  8', '2003-06-11 00:47:17.000000', NULL, 1),
(321236, 24026, 6900, '<td valign="top">The staple remover always wins.  Wish the white paper wasn''t here - or a less cluttered bg - good job in meeting the challenge, however.  8</td>', 'The staple remover always wins.  Wish the white paper wasn''t here - or a less cluttered bg - good job in meeting the challenge, however.  8', '2003-06-11 00:48:53.000000', NULL, 1),
(321238, 23750, 6900, '<td valign="top">Nice office.  Wish the sky were blue to set it off from the building more, but that''s a minor point.</td>', 'Nice office.  Wish the sky were blue to set it off from the building more, but that''s a minor point.', '2003-06-11 00:49:22.000000', NULL, 1),
(321239, 24202, 6900, '<td valign="top">These weren''t managing my stress - I threw them out the window.  Good capture of the reflections - I wish the top of the balls and top right were not so blown out as to be almost blending in the bg.  8</td>', 'These weren''t managing my stress - I threw them out the window.  Good capture of the reflections - I wish the top of the balls and top right were not so blown out as to be almost blending in the bg.  8', '2003-06-11 00:50:01.000000', NULL, 1),
(321241, 23782, 6900, '<td valign="top">Good photojournalism shot - nothing exceptional, but good recording of what''s there.</td>', 'Good photojournalism shot - nothing exceptional, but good recording of what''s there.', '2003-06-11 00:51:00.000000', NULL, 1),
(321243, 24100, 6900, '<td valign="top">Funny - wonder if it''s the same person as the candies or someone copying the technique.  Either way, interesting colors - the yellows and greens have a strange feel to them, while the blue is almost perfect.  Focus is a tad off here.  Great composition.  9</td>', 'Funny - wonder if it''s the same person as the candies or someone copying the technique.  Either way, interesting colors - the yellows and greens have a strange feel to them, while the blue is almost perfect.  Focus is a tad off here.  Great composition.  9', '2003-06-11 00:52:02.000000', NULL, 1),
(321368, 24004, 6893, '<td valign="top">Humor at the work place can be good.</td>', 'Humor at the work place can be good.', '2003-06-11 02:11:17.000000', NULL, 1),
(321372, 24046, 6893, '<td valign="top">A good graph can give a person goose bumps but then so can art.</td>', 'A good graph can give a person goose bumps but then so can art.', '2003-06-11 02:12:21.000000', NULL, 1),
(321375, 24178, 6893, '<td valign="top">Art as caos? hmm I''ll have to think about that one.</td>', 'Art as caos? hmm I''ll have to think about that one.', '2003-06-11 02:13:07.000000', NULL, 1),
(321380, 24264, 6893, '<td valign="top">I''ve seen a lot of date stamps but never really ever consider them artsy.</td>', 'I''ve seen a lot of date stamps but never really ever consider them artsy.', '2003-06-11 02:14:49.000000', NULL, 1),
(321386, 24138, 6893, '<td valign="top">If a Campbells Soup Can is Pop art then this must be topless art.</td>', 'If a Campbells Soup Can is Pop art then this must be topless art.', '2003-06-11 02:16:53.000000', NULL, 1),
(321391, 24204, 6893, '<td valign="top">This is the closest to art yet.  Super creative effort. 8</td>', 'This is the closest to art yet.  Super creative effort. 8', '2003-06-11 02:18:09.000000', NULL, 1),
