(322273, 23925, 6900, '<td valign="top">The background is a bit cluttered and it looks a little low contrast, but interesting subject and nice idea.</td>', 'The background is a bit cluttered and it looks a little low contrast, but interesting subject and nice idea.', '2003-06-11 14:17:12.000000', NULL, 1),
(322274, 24246, 7711, '<td valign="top">I really like this "3D" composition, its very clever! Nice bight colours too, maybe a bit too bright, but on second thought..nah. I like the crowding too, it works well for the shot. Great idea!</td>', 'I really like this "3D" composition, its very clever! Nice bight colours too, maybe a bit too bright, but on second thought..nah. I like the crowding too, it works well for the shot. Great idea!', '2003-06-11 14:17:42.000000', NULL, 1),
