(322280, 24256, 7711, '<td valign="top">I like the dark background and its texture against the abstract smoothness of your "sculpture", very creative. Focus is good too, I like the DOF. I know the bottom of the holder is not totally in focus, but its not distracting and works for the shot.</td>', 'I like the dark background and its texture against the abstract smoothness of your "sculpture", very creative. Focus is good too, I like the DOF. I know the bottom of the holder is not totally in focus, but its not distracting and works for the shot.', '2003-06-11 14:19:11.000000', NULL, 1),
(322281, 24142, 6900, '<td valign="top">Ok, fan it more.  lol  Interesting idea, nice pattern. and decent gradient lighting.  I like it.  7</td>', 'Ok, fan it more.  lol  Interesting idea, nice pattern. and decent gradient lighting.  I like it.  7', '2003-06-11 14:19:29.000000', NULL, 1),
(322282, 24219, 6900, '<td valign="top">Office art?</td>', 'Office art?', '2003-06-11 14:19:49.000000', NULL, 1),
(322283, 23799, 7711, '<td valign="top">I like the full composition, but the huge glare/hotspot on the left is throwing the shot off. My dad was a draftsman and used to design all sorts of structures, so this really brings back some fond memories for me. Thank you.</td>', 'I like the full composition, but the huge glare/hotspot on the left is throwing the shot off. My dad was a draftsman and used to design all sorts of structures, so this really brings back some fond memories for me. Thank you.', '2003-06-11 14:20:53.000000', NULL, 1),
(322285, 24275, 7711, '<td valign="top">this is more like a painting than a photograph, its very creative post processing, but I suspect its not faring as well as you''d like with the voters. Still, nice treatment of an otherwise simple and plain subject. :)</td>', 'this is more like a painting than a photograph, its very creative post processing, but I suspect its not faring as well as you''d like with the voters. Still, nice treatment of an otherwise simple and plain subject. :)', '2003-06-11 14:22:01.000000', NULL, 1),
(322288, 24187, 7711, '<td valign="top">GREAT leading line and wonderful use of negative space. I love the lit blue scroller, it makes this composition really pop. Well done!! :)</td>', 'GREAT leading line and wonderful use of negative space. I love the lit blue scroller, it makes this composition really pop. Well done!! :)', '2003-06-11 14:23:04.000000', NULL, 1),
(322290, 23655, 6900, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2003-06-11 14:25:05.000000', NULL, 1),
