(323743, 24231, 6600, '<td valign="top">Nice detail throughout (border detracts from shot).</td>', 'Nice detail throughout (border detracts from shot).', '2003-06-12 19:21:56.000000', NULL, 1),
(323749, 24253, 332, '<td valign="top">I would have skipped the Toshiba logo. Beside that a great photo. Good DOF and that blue tone is just brilliant. Probably the best picture in this challenge. Great job.</td>', 'I would have skipped the Toshiba logo. Beside that a great photo. Good DOF and that blue tone is just brilliant. Probably the best picture in this challenge. Great job.', '2003-06-12 19:23:48.000000', NULL, 1),
(323769, 24228, 332, '<td valign="top">Great contrast. Love that red/orange color. Good composition. The thing in the upper right corner. The black stuff kinda bothers me. One of the best in this challenge. Top 3 with out a doubt. Good job.</td>', 'Great contrast. Love that red/orange color. Good composition. The thing in the upper right corner. The black stuff kinda bothers me. One of the best in this challenge. Top 3 with out a doubt. Good job.', '2003-06-12 19:40:39.000000', NULL, 1),
(323817, 24026, 9361, '<td valign="top">This is hilarious!! It would greatly brighten any dull office''s atmosphere!!</td>', 'This is hilarious!! It would greatly brighten any dull office''s atmosphere!!', '2003-06-12 21:01:00.000000', NULL, 1),
(323875, 24185, 3540, '<td valign="top">Good sharp clear picture.  Just doesn''t have the visual impact that I''d like to see</td>', 'Good sharp clear picture.  Just doesn''t have the visual impact that I''d like to see', '2003-06-12 22:31:53.000000', NULL, 1),
(323876, 23972, 3540, '<td valign="top">I''m looking at one of these right now.  So I''m thinking I don''t need a picture of it too.  The keyboard is enough.  This is awful bright too...</td>', 'I''m looking at one of these right now.  So I''m thinking I don''t need a picture of it too.  The keyboard is enough.  This is awful bright too...', '2003-06-12 22:32:46.000000', NULL, 1),
(323877, 24233, 3540, '<td valign="top">Good sharp clear pic.   I don''t like the lines between the 2 groups of paperclips particularly.   COlors are well portrayed in this pic.</td>', 'Good sharp clear pic.   I don''t like the lines between the 2 groups of paperclips particularly.   COlors are well portrayed in this pic.', '2003-06-12 22:33:44.000000', NULL, 1),
(323881, 24006, 3540, '<td valign="top">I used to have highlighters like that.  I thought they came from Japan though.  I''ve never seen another like it.  This photo needs to be a little less flat and have a little more "wow"factor in it.</td>', 'I used to have highlighters like that.  I thought they came from Japan though.  I''ve never seen another like it.  This photo needs to be a little less flat and have a little more "wow"factor in it.', '2003-06-12 22:36:16.000000', NULL, 1),
(323920, 24266, 6597, '<td valign="top">I''d say this a little extremecasual but a goo photo never the less</td>', 'I''d say this a little extremecasual but a goo photo never the less', '2003-06-12 23:59:21.000000', NULL, 1),
(323950, 24138, 7556, '<td valign="top">Black background is good choice, great composition &amp; colors...<br/>JB</td>', 'Black background is good choice, great composition & colors...JB', '2003-06-13 01:03:15.000000', NULL, 1),
